import {mkdir,readFile,writeFile} from 'node:fs/promises';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {ProgramBuilder,cgExtra,musicExtra,sceneExtra,achievement,extrasCatalog,unlockExtra,sceneMarker,instruction,imagePut,audioTrack,randomI32,variable,expr as E} from 'galbox-sdk/port-kit';
import {parseProgram,bool,string,i32} from 'galbox-sdk/protocol';
import {createReleaseManifest,inspectResource} from 'galbox-sdk/release';
const root='tests/player-app/public/extras';await mkdir(root,{recursive:true});const old=parseProgram(JSON.parse(await readFile('tests/fixtures/game-data/standard-novel/program.json','utf8'))),media=parseProgram(JSON.parse(await readFile('tests/fixtures/game-data/media-novel/program.json','utf8'))),b=new ProgramBuilder({gameId:'lighthouse-collection',release:'collection-1',entry:'main',title:'灯塔来信 · 收藏室'}).rng(71);
function image(id:string){const a=old.assets.find(a=>a.id===id);if(!a)throw new Error(id);return b.asset('image',{...a,path:'../'+a.path});}function audio(id:string){const a=media.assets.find(a=>a.id===id);if(!a)throw new Error(id);return b.asset('audio',{...a,path:'../media/'+a.path});}
const shore=image('shore'),tower=image('tower'),letter=image('envelope'),lamp=image('lamp'),sea=audio('bgm-long'),voice=audio('voice-opus'),signal=audio('signal-mp3'),short=audio('voice-buffer');
const day=cgExtra('day',[shore,tower],{title:'两面的风景',unlock:E.flag(true)}),mail=cgExtra('letter',[letter],{title:'被收好的信',unlock:E.profile('bool','collected',bool(false))}),secret=cgExtra('secret',[lamp],{title:'回放里的灯'}),music=musicExtra('sea',sea,{title:'海风的旋律',gain:.3,loop:true,unlock:E.flag(true)}),signalMusic=musicExtra('signal',signal,{title:'短波信号',gain:.4,loop:false}),bufferMusic=musicExtra('small',short,{title:'桌边的小调',gain:.5,loop:true,unlock:E.flag(true)}),scene=sceneExtra('memory','memory',{title:'信中的小小场景',unlock:E.wasRead('collection.welcome','zh-1')}),badge=achievement('collector',{title:'第一封收藏',description:'收好一封回信。',icon:letter,unlock:E.profile('bool','collected',bool(false))});b.extras(extrasCatalog('lighthouse-extras','v1',[day,mail,secret,music,signalMusic,bufferMusic,scene,badge]));const roll=variable('roll','i32');b.global({id:'token',kind:'string',initial:string('default')}).global({id:'answer',kind:'string',initial:string('untouched')}).global({...roll,initial:i32(0)});
const page=(at:string,id:string,text:string)=>instruction('text.page',{at,textId:id,revision:'zh-1',speaker:'澪',content:text});
b.function({id:'main',entry:'main:stage',layout:1,params:[],locals:[],returns:'void',code:[imagePut('main:stage','background',shore,{x:0,y:0,alpha:1}),audioTrack('main:music','bgm',sea,{channel:'bgm',gain:.1,loop:true,restore:'replay'}),instruction('value.set',{at:'main:token',dest:'token',value:{literal:string('main-run')}}),page('main:welcome','collection.welcome','收藏室里装着灯塔收到的声音、风景和故事。翻过这一页，再看看菜单里新亮起的收藏。'),instruction('profile.set',{at:'main:collect',key:'collected',value:bool(true)}),unlockExtra('main:signal',signalMusic),page('main:reading','collection.reading','你可以打开CG、试听音乐，或走进信里的小场景。关闭鉴赏后，我们仍在这里继续读信。'),instruction('profile.set',{at:'main:reset',key:'collected',value:bool(false)}),page('main:closing','collection.closing','收集标记已经复位，但风景与成就仍会保留。只有回放里点亮的那盏灯，不会偷偷进入主线收藏。'),instruction('control.end',{at:'main:end'})]});
b.function({id:'memory',entry:'memory:scene',layout:1,params:[],locals:[{id:'local',kind:'i32',initial:i32(9)}],returns:'void',code:[sceneMarker('memory:scene',scene),imagePut('memory:stage','background',tower,{x:0,y:0,alpha:1}),instruction('value.set',{at:'memory:token',dest:'token',value:{literal:string('replay-run')}}),randomI32('memory:roll',roll,E.integer(1),E.integer(99)),instruction('profile.set',{at:'memory:leak',key:'replayLeak',value:bool(true)}),unlockExtra('memory:secret',secret),audioTrack('memory:voice','voice',voice,{channel:'voice',gain:.4,restore:'replay'}),page('memory:first','collection.memory','这是收藏室里的独立回放。这里的变量、已读和新收藏都只属于这一次回放。'),instruction('choice',{at:'memory:choice',dest:'answer',options:[{id:'left',text:'把回声留在窗边',target:'memory:ending'},{id:'right',text:'把回声写在纸上',target:'memory:ending'}]}),instruction('profile.set',{at:'memory:ending',key:'replayEnding',value:bool(true)}),page('memory:last','collection.memory-end','小场景结束了。关闭鉴赏，就能回到原来那封尚未读完的信。'),instruction('control.return',{at:'memory:return'})]});
const program=b.build(),resources=await Promise.all(program.assets.map(async a=>inspectResource(a,new Uint8Array(await readFile(path.resolve(root,a.path))),bytes=>new TextDecoder('utf-8',{fatal:true}).decode(bytes))));const release=await createReleaseManifest({program,series:'1',resources},{async sha256(text){return createHash('sha256').update(text).digest('hex');}});for(const target of [root,'tests/fixtures/game-data/extras-novel']){await mkdir(target,{recursive:true});await writeFile(target+'/program.json',JSON.stringify(program,null,2)+'\n');await writeFile(target+'/program.json.release.json',JSON.stringify(release,null,2)+'\n');}console.log('Built original collection chapter with CG variants, buffer/element music, latched achievement and isolated scene root');
